// strike frames of the authored attack clips (seconds), see tools/rigging/jedi_clips.py
static float StrikeTime(FName N)
{
	if (N == TEXT("saber_attack_1")) return 0.42f;
	if (N == TEXT("saber_attack_2")) return 0.40f;
	if (N == TEXT("saber_attack_3")) return 0.50f;
	if (N == TEXT("saber_thrust")) return 0.38f;
	return 0.4f;
}
static const FName GCombo[] = { TEXT("saber_attack_1"), TEXT("saber_attack_2"), TEXT("saber_attack_3"), TEXT("saber_thrust") };

ADukeJedi::ADukeJedi()
{
	Faction = EDukeFaction::Alliance;
	AssetPath = TEXT("/Game/DukeForge/Characters/Jedi");
	MaxHealth = 250.f; PatrolSpeed = 130.f; CombatMoveSpeed = 260.f; PreferredRange = FVector2D(120.f, 170.f);
	WoundChance = 0.f; RollChance = 0.f;
}

void ADukeJedi::BeginPlay() { Super::BeginPlay(); }

void ADukeJedi::DrawSaber(float Now)
{
	if (bSaberDrawn) return;
	if (UDukeTrooperAnimInstance* A = Anim()) { A->PlayAction(TEXT("draw_saber")); BusyUntil = Now + A->ClipLength(TEXT("draw_saber")); }
	bSaberDrawn = true; bDrawing = true; DrawnAt = Now;
}
void ADukeJedi::HolsterSaber(float Now)
{
	if (!bSaberDrawn) return;
	if (UDukeTrooperAnimInstance* A = Anim()) { A->PlayAction(TEXT("holster_saber")); BusyUntil = Now + A->ClipLength(TEXT("holster_saber")); }
	bSaberDrawn = false; bDrawing = false;
}

void ADukeJedi::EnterCombat(AActor* Who, float Now, bool bSignal)
{
	ADukeTrooper::EnterCombat(Who, Now, false);   // no hand signal: he draws the saber instead
	LastEnemySeen = Now;
	DrawSaber(Now);
}

void ADukeJedi::Tick(float Dt)
{
	Super::Tick(Dt);
	const float Now = GetWorld()->GetTimeSeconds();
	if (bDrawing && Now - DrawnAt > 1.1f) bDrawing = false;            // blade lit at ~1.0 s of draw_saber
	if (UDukeTrooperAnimInstance* A = Anim())
	{
		A->State.bAiming = bSaberDrawn && !IsDead();                   // guard locomotion (aim_walk_*) while the saber is out
		A->State.bCrouched = false;
	}
	if (StrikeAt > 0.f && Now >= StrikeAt) { StrikeAt = -1.f; Strike(Now); }
	if (ForceAt > 0.f && Now >= ForceAt) { ForceAt = -1.f; DoForce(Now); }
	// combat over: switch off and hang the hilt back on the belt
	if (bSaberDrawn && !IsDead() && State != EDukeTrooperState::Combat && Now - LastEnemySeen > HolsterAfter && Now > BusyUntil) HolsterSaber(Now);
}

void ADukeJedi::TickCombat(float Dt, float Now)
{
	AActor* T = Target.Get();
	if (!T || !IsHostileTo(T)) { if (AActor* E = FindEnemy()) { Target = E; T = E; } else { State = EDukeTrooperState::Patrol; return; } }
	const bool bSee = CanSee(T);
	if (bSee) { LastSeen = T->GetActorLocation(); LastSeenTime = Now; LastEnemySeen = Now; }
	if (Now - LastSeenTime > 8.f) { State = EDukeTrooperState::Patrol; Target = nullptr; return; }
	const FVector To = (LastSeen - GetActorLocation()) * FVector(1, 1, 0);
	const float Dist = To.Size();
	SetActorRotation(FMath::RInterpTo(GetActorRotation(), To.Rotation(), Dt, 9.f));
	if (Now < BusyUntil || Now < ActionLock) return;

	// the Force: push when two or more enemies are close in front, pull a lone shooter who keeps his distance
	if (Now >= NextForce)
	{
		int32 Close = 0;
		for (TActorIterator<APawn> It(GetWorld()); It; ++It)
			if (IsHostileTo(*It) && FVector::Dist(It->GetActorLocation(), GetActorLocation()) < PushRange &&
				FVector::DotProduct(GetActorForwardVector(), (It->GetActorLocation() - GetActorLocation()).GetSafeNormal2D()) > 0.5f) ++Close;
		FName Kind = Close >= 2 ? FName(TEXT("force_push")) : (Dist > 700.f && Dist < PullRange && bSee ? FName(TEXT("force_pull")) : NAME_None);
		if (Kind != NAME_None)
			if (UDukeTrooperAnimInstance* A = Anim())
			{
				A->PlayAction(Kind); ForceKind = Kind; ForceAt = Now + (Kind == TEXT("force_push") ? 0.40f : 0.45f);
				BusyUntil = Now + A->ClipLength(Kind) * 0.85f; NextForce = Now + ForceCooldown; return;
			}
	}
	// close in (guard walk / run), then attack in a chained combo
	UCharacterMovementComponent* Move = GetCharacterMovement();
	Move->MaxWalkSpeed = Dist > 600.f ? 420.f : CombatMoveSpeed;
	if (Dist > StrikeRange * 0.8f) { AddMovementInput(To.GetSafeNormal(), 1.f); return; }
	if (Now >= NextAttack)
		if (UDukeTrooperAnimInstance* A = Anim())
		{
			const FName Clip = GCombo[Combo % 4]; ++Combo;
			A->PlayAction(Clip); StrikeAt = Now + StrikeTime(Clip);
			const float Len = A->ClipLength(Clip);
			BusyUntil = Now + Len * 0.8f;                           // chains into the next swing from the recovery
			NextAttack = Now + Len * (Combo % 4 == 0 ? 1.4f : 0.85f); // a short pause after the full combo
		}
}

void ADukeJedi::Strike(float Now)
{
	AActor* T = Target.Get();
	if (!T || IsDead()) return;
	const FVector To = T->GetActorLocation() - GetActorLocation();
	if (To.Size2D() > StrikeRange || FVector::DotProduct(GetActorForwardVector(), To.GetSafeNormal2D()) < 0.3f) return;   // swung at air
	FPointDamageEvent E(SaberDamage, FHitResult(), To.GetSafeNormal(), UDukeSaberDamageType::StaticClass());
	T->TakeDamage(SaberDamage, E, GetController(), this);
}

void ADukeJedi::DoForce(float Now)
{
	const FVector Me = GetActorLocation();
	if (ForceKind == TEXT("force_push"))
	{
		for (TActorIterator<ACharacter> It(GetWorld()); It; ++It)
		{
			ACharacter* C = *It; if (!IsHostileTo(C)) continue;
			const FVector D = C->GetActorLocation() - Me; if (D.Size() > PushRange || FVector::DotProduct(GetActorForwardVector(), D.GetSafeNormal2D()) < 0.5f) continue;
			const float K = 1.f - D.Size() / PushRange;
			C->LaunchCharacter(D.GetSafeNormal2D() * PushStrength * (0.5f + K) + FVector(0, 0, 350.f * (0.5f + K)), true, true);
			FRadialDamageEvent RE; RE.DamageTypeClass = UDukeExplosionDamageType::StaticClass(); RE.Origin = Me;
			C->TakeDamage(25.f + 40.f * K, RE, GetController(), this);     // a hard landing; close ones are thrown limp
		}
	}
	else if (ACharacter* C = Cast<ACharacter>(Target.Get()))
	{
		const FVector D = Me - C->GetActorLocation();
		C->LaunchCharacter(D.GetSafeNormal2D() * FMath::Min(D.Size() * 1.6f, 1600.f) + FVector(0, 0, 260.f), true, true);   // yanked toward the Jedi
	}
}

float ADukeJedi::TakeDamage(float DamageAmount, FDamageEvent const& DamageEvent, AController* EventInstigator, AActor* DamageCauser)
{
	const float Now = GetWorld()->GetTimeSeconds();
	const UClass* DT = DamageEvent.DamageTypeClass ? DamageEvent.DamageTypeClass.Get() : nullptr;
	const bool bBolt = Cast<ADukeBlasterBolt>(DamageCauser) != nullptr;
	if (bBolt && IsSaberLit() && !IsDead() && DamageEvent.IsOfType(FPointDamageEvent::ClassID))
	{
		const FPointDamageEvent& PE = static_cast<const FPointDamageEvent&>(DamageEvent);
		const FVector In = -PE.ShotDirection.GetSafeNormal();
		const float Front = FVector::DotProduct(GetActorForwardVector(), In);
		if (Front > 0.2f && FMath::FRand() < DeflectChance)
		{
			// meet the bolt with the blade and bat it away - often straight back at the shooter
			const float Side = FVector::DotProduct(GetActorRightVector(), In);
			const FName Clip = PE.HitInfo.ImpactPoint.Z > GetActorLocation().Z + 60.f ? FName(TEXT("saber_deflect_high")) : (Side > 0.f ? FName(TEXT("saber_deflect_r")) : FName(TEXT("saber_deflect_l")));
			if (UDukeTrooperAnimInstance* A = Anim()) A->PlayAction(Clip, 1.4f);
			ActionLock = FMath::Max(ActionLock, Now + 0.3f);
			const FVector From = GetActorLocation() + GetActorForwardVector() * 60.f + FVector(0, 0, 40.f);
			AActor* Shooter = EventInstigator && EventInstigator->GetPawn() ? EventInstigator->GetPawn() : nullptr;
			FVector Dir = FMath::VRandCone(In, FMath::DegreesToRadians(35.f));
			if (Shooter && FMath::FRand() < ReflectAccuracy) Dir = (Shooter->GetActorLocation() + FVector(0, 0, 30.f) - From).GetSafeNormal();
			const ADukeBlasterBolt* B = Cast<ADukeBlasterBolt>(DamageCauser);
			ADukeBlasterBolt::Fire(GetWorld(), this, From, Dir, DamageAmount, 9000.f, B ? B->BoltColor : FLinearColor(1.f, 0.06f, 0.04f));
			return 0.f;
		}
	}
	return Super::TakeDamage(DamageAmount, DamageEvent, EventInstigator, DamageCauser);
}
